# ---------- root & fields
S.add('soc', 'root', t('جامعه', 'Society', 'Samenleving'),
      t('چرا آدم‌ها در جمع طوری رفتار می‌کنند که هیچ‌کدام به‌تنهایی نمی‌کردند؟ این ویکی مفاهیم جامعه‌شناسی را با شواهد پیمایشی و تجربی کنار هم می‌گذارد: اعتماد و سرمایهٔ اجتماعی، نابرابری، نهادها، کنش جمعی، ارزش‌ها و نسل‌ها، شهر و مهاجرت، شبکه‌ها؛ با نگاهی ویژه به داده‌های ایران.',
        'Why do people in groups behave in ways none of them would alone? This wiki brings sociology\'s concepts together with survey and experimental evidence: trust and social capital, inequality, institutions, collective action, values and generations, city and migration, networks; with special attention to data on Iran.',
        'Waarom gedragen mensen zich in groepen zoals geen van hen alleen zou doen? Deze wiki brengt de concepten van de sociologie samen met survey- en experimenteel bewijs: vertrouwen en sociaal kapitaal, ongelijkheid, instituties, collectieve actie, waarden en generaties, stad en migratie, netwerken; met bijzondere aandacht voor data over Iran.'),
      links=[ln('psy:p-social', 'bridges', 'روان‌شناسی اجتماعی در ویکی روان', 'Social psychology in the psychology wiki'), ln('psy:social-capital', 'bridges', 'سرمایهٔ اجتماعی در ویکی روان', 'Social capital in the psychology wiki'), ln('psy:anomie', 'bridges', 'آنومی در ویکی روان', 'Anomie in the psychology wiki')])

F = [
 ('theory', t('نظریهٔ اجتماعی', 'Social theory', 'Sociale theorie'), t('ابزارهای فکری پایه: از بینش جامعه‌شناختی تا ساخت اجتماعی واقعیت و نمایش خود.', 'The basic thinking tools: from the sociological imagination to the social construction of reality and the presentation of self.', 'De basisdenkgereedschappen: van de sociologische verbeelding tot de sociale constructie van de werkelijkheid en de presentatie van het zelf.')),
 ('cohesion', t('انسجام، اعتماد و سرمایهٔ اجتماعی', 'Cohesion, trust & social capital', 'Cohesie, vertrouwen & sociaal kapitaal'), t('چه چیزی جامعه را کنار هم نگه می‌دارد و وقتی می‌شکند چه می‌شود؟', 'What holds a society together, and what happens when it breaks?', 'Wat houdt een samenleving bijeen, en wat gebeurt er als het breekt?')),
 ('inequality', t('نابرابری و تحرک', 'Inequality & mobility', 'Ongelijkheid & mobiliteit'), t('چقدر فاصله هست، چقدر می‌شود از آن بالا رفت، و نابرابری با جامعه چه می‌کند؟', 'How wide is the gap, how climbable is it, and what does inequality do to a society?', 'Hoe groot is de kloof, hoe beklimbaar is ze, en wat doet ongelijkheid met een samenleving?')),
 ('institutions', t('نهادها و دولت', 'Institutions & the state', 'Instituties & de staat'), t('قواعد بازی، فراگیر یا بهره‌کش، چگونه سرنوشت ملت‌ها را شکل می‌دهند؟', 'How do the rules of the game, inclusive or extractive, shape nations\' fates?', 'Hoe vormen de spelregels, inclusief of extractief, het lot van naties?')),
 ('collective', t('کنش جمعی و جنبش‌ها', 'Collective action & movements', 'Collectieve actie & bewegingen'), t('چرا مردم گاهی با هم حرکت می‌کنند و بیشتر وقت‌ها نه؛ و چرا انقلاب‌ها همیشه غافلگیر می‌کنند؟', 'Why people sometimes move together and mostly do not; and why revolutions always surprise.', 'Waarom mensen soms samen in beweging komen en meestal niet; en waarom revoluties altijd verrassen.')),
 ('values', t('ارزش‌ها، دین و نسل‌ها', 'Values, religion & generations', 'Waarden, religie & generaties'), t('ارزش‌ها چگونه با توسعه عوض می‌شوند، دین چه می‌شود و نسل‌ها از کجا متفاوت می‌شوند؟', 'How values shift with development, what happens to religion, and where generations diverge.', 'Hoe waarden verschuiven met ontwikkeling, wat er met religie gebeurt en waar generaties uiteenlopen.')),
 ('space', t('شهر، مهاجرت و شبکه', 'City, migration & networks', 'Stad, migratie & netwerken'), t('زندگی شهری، حرکت مردم و شبکه‌هایی که ایده‌ها و رفتارها در آن پخش می‌شوند.', 'Urban life, the movement of people and the networks through which ideas and behaviours spread.', 'Stedelijk leven, de beweging van mensen en de netwerken waarlangs ideeën en gedrag zich verspreiden.')),
]
for fid, title, summ in F: S.add(fid, 'field', title, summ, parent='soc')

# ---------- theory
S.add('sociological-imagination', 'concept', t('بینش جامعه‌شناختی', 'The sociological imagination', 'De sociologische verbeelding'),
      t('توان دیدن پیوند میان «گرفتاری‌های شخصی» و «مسائل عمومی»: بیکاری یک نفر مشکل اوست؛ بیکاری یک‌پنجم جامعه مسئله‌ای ساختاری است که با نصیحت فردی حل نمی‌شود.', 'The capacity to see the link between "personal troubles" and "public issues": one person\'s unemployment is their trouble; a fifth of society unemployed is a structural issue no individual advice will fix.', 'Het vermogen om het verband te zien tussen "persoonlijke moeilijkheden" en "publieke kwesties": de werkloosheid van één persoon is diens probleem; een vijfde van de samenleving werkloos is een structurele kwestie die geen individueel advies oplost.'),
      parent='theory', field='theory', people=[P['mills']],
      points=[pt('میلز (۱۹۵۹): جامعه‌شناسی یعنی پیوند زدن زندگی‌نامه و تاریخ؛ هر مشکل فردی را باید پرسید در چه ساختاری و در چه دوره‌ای پدید آمده.', 'Mills (1959): sociology means connecting biography and history; of every personal problem ask in what structure and what era it arose.', [mills]),
              pt('این نگاه پادزهر «روان‌شناسی‌زدگی» است: تبدیل مسائل ساختاری (مسکن، اشتغال) به ضعف اراده یا شخصیت افراد.', 'This view is the antidote to "psychologism": turning structural problems (housing, jobs) into individuals\' failures of will or character.', [mills])],
      links=[ln('psy:medicalization', 'bridges', 'پزشکی‌سازی در ویکی روان', 'Medicalization in the psychology wiki'), ln('soc:social-construction', 'see-also', 'ساخت اجتماعی واقعیت', 'The social construction of reality')])

S.add('social-construction', 'concept', t('ساخت اجتماعی واقعیت', 'The social construction of reality', 'De sociale constructie van de werkelijkheid'),
      t('پول، ازدواج، مرز، «نوجوانی»: چیزهایی که فقط چون همه باور دارند وجود دارند و با این حال کاملاً واقعی‌اند. ساخت اجتماعی یعنی «ساخته‌شده»، نه «خیالی».', 'Money, marriage, borders, "adolescence": things that exist only because everyone believes in them, and are nonetheless entirely real. Socially constructed means "made", not "imaginary".', 'Geld, huwelijk, grenzen, "adolescentie": dingen die alleen bestaan omdat iedereen erin gelooft, en toch volkomen echt zijn. Sociaal geconstrueerd betekent "gemaakt", niet "ingebeeld".'),
      parent='theory', field='theory',
      points=[pt('برگر و لاکمن (۱۹۶۶): واقعیت اجتماعی در سه حرکت ساخته می‌شود: برونی‌سازی (آدم‌ها عادت می‌سازند)، عینیت‌یافتگی (عادت به نهاد تبدیل می‌شود و «همیشه همین‌طور بوده») و درونی‌سازی (نسل بعد آن را طبیعی می‌بیند).', 'Berger and Luckmann (1966): social reality is built in three moves: externalisation (people make habits), objectivation (the habit becomes an institution that "was always so") and internalisation (the next generation sees it as natural).', [berger]),
              pt('هکینگ (۱۹۹۹): گفتن «X ساخت اجتماعی است» وقتی معنادار است که X اجتناب‌ناپذیر فرض شده باشد؛ و بعضی ساخته‌ها «نوع‌های تعاملی»اند: برچسب، رفتار برچسب‌خورده را عوض می‌کند (اثر حلقه‌ای).', 'Hacking (1999): saying "X is socially constructed" is meaningful when X was assumed inevitable; and some constructs are "interactive kinds": the label changes the behaviour of the labelled (the looping effect).', [hacking])],
      links=[ln('psy:dx', 'bridges', 'تشخیص روان‌پزشکی به‌عنوان نوع تعاملی', 'Psychiatric diagnosis as an interactive kind'), ln('tabar:race-biology', 'bridges', 'نژاد: ساخت اجتماعی با پیامد واقعی', 'Race: a social construct with real consequences')])

S.add('presentation-of-self', 'concept', t('نمایش خود در زندگی روزمره', 'The presentation of self', 'De presentatie van het zelf'),
      t('گافمن زندگی اجتماعی را صحنهٔ تئاتر می‌بیند: «جلوی صحنه» نقش بازی می‌کنیم، «پشت صحنه» استراحت؛ و آبرو (face) چیزی است که همه در حفظش همکاری می‌کنند.', 'Goffman sees social life as theatre: "front stage" we perform, "backstage" we rest; and face is something everyone cooperates to protect.', 'Goffman ziet het sociale leven als theater: "op het toneel" spelen we, "achter de schermen" rusten we; en gezicht is iets dat iedereen samen beschermt.'),
      parent='theory', field='theory', people=[P['goffman']],
      points=[pt('گافمن (۱۹۵۹): مدیریت تأثیر امری همگانی و نه ریاکارانه است؛ بدون آن تعامل روزمره ممکن نیست. شبکه‌های اجتماعی «جلوی صحنه»ای دائمی ساخته‌اند و پشت صحنه را کوچک کرده‌اند.', 'Goffman (1959): impression management is universal, not hypocrisy; everyday interaction is impossible without it. Social media have built a permanent front stage and shrunk the backstage.', [goffman])],
      links=[ln('psy:narcissism-culture', 'bridges', 'فرهنگ خودشیفتگی در ویکی روان', 'Narcissism culture in the psychology wiki'), ln('psy:emotional-labor', 'bridges', 'کار هیجانی', 'Emotional labour')])

# ---------- cohesion
S.add('anomie', 'concept', t('آنومی (بی‌هنجاری)', 'Anomie', 'Anomie'),
      t('وقتی قواعد مشترک سست می‌شوند یا میان هدف‌های تبلیغ‌شده و راه‌های مجاز رسیدن به آن‌ها شکاف می‌افتد؛ دورکیم آن را با خودکشی، مرتون با کج‌روی پیوند زد.', 'When shared rules loosen, or a gap opens between advertised goals and the legitimate means of reaching them; Durkheim tied it to suicide, Merton to deviance.', 'Wanneer gedeelde regels verslappen, of een kloof ontstaat tussen de aangeprezen doelen en de legitieme middelen om ze te bereiken; Durkheim verbond het met zelfdoding, Merton met deviantie.'),
      parent='cohesion', field='cohesion', people=[P['durkheim'], P['merton']],
      points=[pt('دورکیم (۱۸۹۷): نرخ خودکشی واقعیتی اجتماعی است، نه جمع تصمیم‌های فردی؛ در دوره‌های تغییر تند اقتصادی (هم رونق، هم رکود) بالا می‌رود چون معیارهای «کافی» گم می‌شوند.', 'Durkheim (1897): the suicide rate is a social fact, not the sum of individual decisions; it rises in periods of rapid economic change (boom as much as bust) because the standards of "enough" are lost.', [durk_suicide]),
              pt('مرتون (۱۹۳۸): وقتی فرهنگ همه را به هدف واحدی (ثروت) می‌خواند ولی ساختار راه مشروع را برای همه باز نمی‌گذارد، پنج پاسخ پدید می‌آید: همنوایی، نوآوری (کج‌روی)، مناسک‌گرایی، انزوا، شورش.', 'Merton (1938): when culture calls everyone to the same goal (wealth) but structure keeps legitimate paths closed to many, five adaptations appear: conformity, innovation (deviance), ritualism, retreatism, rebellion.', [merton])],
      links=[ln('psy:anomie', 'same-as', 'همین مفهوم در ویکی روان، با تأکید روانی', 'The same concept in the psychology wiki, with the psychological emphasis'), ln('soc:inequality-health', 'see-also', 'نابرابری و سلامت', 'Inequality and health')])

S.add('social-capital', 'concept', t('سرمایهٔ اجتماعی: پیوندی و پل‌زننده', 'Social capital: bonding and bridging', 'Sociaal kapitaal: bindend en overbruggend'),
      t('شبکه‌ها، هنجارهای متقابل و اعتمادی که همکاری را ممکن می‌کنند. سرمایهٔ «پیوندی» درون گروه (خانواده، قوم) گرم و محافظ است؛ سرمایهٔ «پل‌زننده» میان گروه‌ها فرصت و اطلاعات می‌آورد. جامعه‌ای که اولی را زیاد و دومی را کم دارد، محفلی و بی‌اعتماد می‌شود.', 'The networks, norms of reciprocity and trust that make cooperation possible. "Bonding" capital within a group (family, clan) is warm and protective; "bridging" capital between groups brings opportunity and information. A society rich in the first and poor in the second becomes cliquish and distrustful.', 'De netwerken, wederkerigheidsnormen en het vertrouwen die samenwerking mogelijk maken. "Bindend" kapitaal binnen een groep (familie, clan) is warm en beschermend; "overbruggend" kapitaal tussen groepen brengt kansen en informatie. Een samenleving rijk aan het eerste en arm aan het tweede wordt kliekerig en wantrouwig.'),
      parent='cohesion', field='cohesion', people=[P['putnam'], P['coleman'], P['bourdieu']],
      points=[pt('پاتنم (۱۹۹۳): تفاوت کارایی حکومت‌های محلی شمال و جنوب ایتالیا را به سنت‌های مدنی چندصدساله (انجمن‌ها، همسرایی‌ها، تعاونی‌ها) برگرداند؛ یکی از پرارجاع‌ترین و پرمناقشه‌ترین مطالعات علوم اجتماعی.', 'Putnam (1993): traced the difference in local-government performance between northern and southern Italy to centuries-old civic traditions (associations, choirs, cooperatives); one of social science\'s most cited and most contested studies.', [putnam1993], ['contested']),
              pt('کلمن (۱۹۸۸): سرمایهٔ اجتماعی در ساختار روابط است، نه در افراد؛ شبکهٔ «بسته» (والدینی که همدیگر را می‌شناسند) هنجارها را اجراپذیر می‌کند و افت تحصیلی را کم.', 'Coleman (1988): social capital lies in the structure of relations, not in individuals; a "closed" network (parents who know each other) makes norms enforceable and cuts school dropout.', [coleman]),
              pt('بوردیو (۱۹۸۶): سرمایهٔ اجتماعی مثل سرمایهٔ اقتصادی و فرهنگی نابرابر توزیع شده و ابزار بازتولید امتیاز است؛ «پارتی» نام محلی همین پدیده است.', 'Bourdieu (1986): social capital, like economic and cultural capital, is unequally distributed and a tool for reproducing privilege; "connections" is the everyday name of the same phenomenon.', [bourdieu])],
      links=[ln('psy:social-capital', 'same-as', 'سرمایهٔ اجتماعی در ویکی روان', 'Social capital in the psychology wiki'), ln('soc:weak-ties', 'explains', 'چرا پیوندهای ضعیف پل می‌زنند', 'Why weak ties bridge'), ln('soc:generalized-trust', 'part-of', 'اعتماد تعمیم‌یافته، هستهٔ سرمایهٔ پل‌زننده', 'Generalised trust, the core of bridging capital')])

S.add('generalized-trust', 'concept', t('اعتماد تعمیم‌یافته', 'Generalised trust', 'Gegeneraliseerd vertrouwen'),
      t('پاسخ به یک سؤال ساده: «به‌طور کلی می‌شود به بیشتر مردم اعتماد کرد یا باید خیلی مراقب بود؟» این عدد میان کشورها از زیر ۱۰ تا بالای ۶۰ درصد فرق می‌کند، دهه‌ها پایدار می‌ماند، و با رشد اقتصادی، سلامت و کیفیت حکمرانی همبسته است. در ایران پایین است.', 'The answer to one simple question: "Generally speaking, can most people be trusted, or must one be very careful?" It ranges from under 10 to over 60 percent across countries, stays stable for decades, and correlates with growth, health and quality of government. In Iran it is low.', 'Het antwoord op één eenvoudige vraag: "Kunnen de meeste mensen over het algemeen worden vertrouwd, of moet men heel voorzichtig zijn?" Het loopt tussen landen van onder de 10 tot boven de 60 procent, blijft decennialang stabiel en hangt samen met groei, gezondheid en bestuurskwaliteit. In Iran is het laag.'),
      parent='cohesion', field='cohesion', iran='iran:social-trust',
      points=[pt('روتشتاین و اوسلانر (۲۰۰۵): برابری (اقتصادی و فرصتی) و نبود فساد قوی‌ترین پیش‌بینی‌کننده‌های اعتماد تعمیم‌یافته‌اند؛ نابرابری اعتماد را می‌خورد و بی‌اعتمادی سیاست‌های برابرساز را ناممکن می‌کند: تلهٔ اجتماعی.', 'Rothstein and Uslaner (2005): equality (economic and of opportunity) and absence of corruption are the strongest predictors of generalised trust; inequality eats trust and distrust makes equalising policies impossible: a social trap.', [rothstein]),
              pt('آلگان و کاهوک (۲۰۱۰): با اعتماد ارثی مهاجران آمریکایی (بر حسب کشور مبدأ) نشان دادند اعتماد علّتِ رشد است نه فقط معلولش؛ اگر اعتماد آفریقا در سطح سوئد بود، درآمد سرانه‌اش چند برابر بود.', 'Algan and Cahuc (2010): using the inherited trust of US immigrants (by country of origin) they showed trust causes growth, not only follows it; had Africa Sweden\'s trust level, its income per head would be several times higher.', [algan], ['contested']),
              pt('در پیمایش جهانی ارزش‌ها، اعتماد تعمیم‌یافتهٔ ایرانیان در موج‌های اخیر در حدود ۱۰ تا ۱۵ درصد و در ردهٔ کشورهای کم‌اعتماد است؛ در پیمایش ملی ارزش‌ها و نگرش‌ها نیز اعتماد به «مردم» از موج اول تا سوم کاهش نشان می‌دهد.', 'In the World Values Survey, Iranians\' generalised trust in recent waves is around 10 to 15 percent, among the low-trust countries; the national Values and Attitudes survey also shows trust in "people" falling from the first to the third wave.', [wvs7, ivas])],
      links=[ln('psy:social-trust', 'same-as', 'اعتماد اجتماعی در ویکی روان (درس اعتماد)', 'Social trust in the psychology wiki (the trust lecture)'), ln('soc:inequality-health', 'explains', 'نابرابری چگونه اعتماد را می‌خورد', 'How inequality eats trust'), ln('soc:institutions-inclusive', 'see-also', 'فساد و نهادها', 'Corruption and institutions')])

S.add('weak-ties', 'concept', t('قدرت پیوندهای ضعیف', 'The strength of weak ties', 'De kracht van zwakke banden'),
      t('شغل‌ها، ایده‌ها و اخبار تازه بیشتر از آشنایان دور می‌رسند تا دوستان نزدیک، چون دوستان نزدیک همان چیزهایی را می‌دانند که ما می‌دانیم. پیوند ضعیف پلِ میان خوشه‌هاست.', 'Jobs, ideas and news arrive more often through acquaintances than close friends, because close friends know what we know. The weak tie is the bridge between clusters.', 'Banen, ideeën en nieuws komen vaker via kennissen dan via goede vrienden, omdat goede vrienden weten wat wij weten. De zwakke band is de brug tussen clusters.'),
      parent='cohesion', field='cohesion', people=[P['granovetter'], P['centola']],
      points=[pt('گرانووتر (۱۹۷۳): از کسانی که از راه آشنا شغل پیدا کرده بودند، بیشترشان آن آشنا را «گاه‌به‌گاه» یا «به‌ندرت» می‌دیدند، نه «اغلب».', 'Granovetter (1973): of those who found a job through a contact, most saw that contact "occasionally" or "rarely", not "often".', [granovetter]),
              pt('سنتولا (۲۰۱۰): اما رفتارهای پرهزینه (ترک سیگار، پیوستن به جنبش) برعکس از راه پیوندهای قوی و پرتکرار پخش می‌شوند: «سرایت پیچیده» به تأیید چند منبع نیاز دارد.', 'Centola (2010): but costly behaviours (quitting smoking, joining a movement) spread instead through strong, redundant ties: "complex contagion" needs confirmation from several sources.', [centola])],
      links=[ln('psy:complex-contagion', 'same-as', 'سرایت پیچیده در ویکی روان', 'Complex contagion in the psychology wiki'), ln('soc:social-capital', 'part-of', 'سازوکار سرمایهٔ پل‌زننده', 'The mechanism of bridging capital')])

# ---------- inequality
S.add('gini-inequality', 'concept', t('اندازه‌گیری نابرابری: ضریب جینی و فراتر از آن', 'Measuring inequality: the Gini and beyond', 'Ongelijkheid meten: de Gini en verder'),
      t('جینی صفر یعنی همه برابر، یک یعنی همه‌چیز دست یک نفر. ایران در دههٔ اخیر حدود ۰٫۴۰ است: بالاتر از اروپا، نزدیک ترکیه و آمریکا، پایین‌تر از آمریکای لاتین. ولی جینی سهم «یک درصد بالا» و ثروت (نه درآمد) را پنهان می‌کند.', 'A Gini of zero means everyone equal, one means everything in one hand. Iran in the last decade is about 0.40: higher than Europe, near Turkey and the US, lower than Latin America. But the Gini hides the "top one percent" share and wealth (as opposed to income).', 'Een Gini van nul betekent iedereen gelijk, één betekent alles in één hand. Iran zit het laatste decennium rond 0,40: hoger dan Europa, dicht bij Turkije en de VS, lager dan Latijns-Amerika. Maar de Gini verbergt het aandeel van de "top één procent" en vermogen (tegenover inkomen).'),
      parent='inequality', field='inequality', iran='iran:gini', people=[P['piketty']],
      points=[pt('بانک جهانی: جینی درآمدی ایران در سال‌های اخیر در بازهٔ ۳۸ تا ۴۲ گزارش شده؛ مرکز آمار ایران ارقام مشابهی می‌دهد و در سال‌های تورم بالا افزایش دیده می‌شود.', 'World Bank: Iran\'s income Gini in recent years is reported in the 38 to 42 range; the Statistical Centre of Iran gives similar figures, rising in high-inflation years.', [wb_gini]),
              pt('پیکتی (۲۰۱۴): وقتی بازده سرمایه از رشد اقتصاد بیشتر باشد (r > g)، ثروت موروثی نسبت به درآمد کار بزرگ می‌شود؛ نابرابری ثروت همه‌جا بسیار بیشتر از نابرابری درآمد است.', 'Piketty (2014): when the return on capital exceeds economic growth (r > g), inherited wealth grows relative to earned income; wealth inequality is everywhere far larger than income inequality.', [piketty], ['contested'])],
      links=[ln('soc:mobility', 'see-also', 'نابرابری فرصت در برابر نابرابری نتیجه', 'Inequality of opportunity versus of outcome'), ln('soc:inequality-health', 'see-also', 'پیامدهای نابرابری', 'The consequences of inequality')])

S.add('mobility', 'concept', t('تحرک بین‌نسلی', 'Intergenerational mobility', 'Intergenerationele mobiliteit'),
      t('چقدر درآمد و جایگاه فرزند به والدینش بسته است؟ در کشورهای اسکاندیناوی کم، در آمریکا و بریتانیا زیاد، و بر خلاف تصور، «رؤیای آمریکایی» در کانادا و دانمارک دست‌یافتنی‌تر است تا در آمریکا.', 'How much does a child\'s income and standing depend on the parents\'? Little in Scandinavia, much in the US and Britain, and contrary to the myth, the "American dream" is more attainable in Canada and Denmark than in America.', 'Hoezeer hangen inkomen en positie van een kind af van de ouders? Weinig in Scandinavië, veel in de VS en Groot-Brittannië, en anders dan de mythe wil, is de "American dream" beter haalbaar in Canada en Denemarken dan in Amerika.'),
      parent='inequality', field='inequality', people=[P['chetty']],
      points=[pt('چتی و همکاران (۲۰۱۴، داده‌های مالیاتی ۴۰ میلیون نفر): تحرک در آمریکا از شهری به شهر دیگر دو تا سه برابر فرق می‌کند؛ پنج همبستهٔ قوی: تفکیک نژادی و فضایی کمتر، نابرابری کمتر، مدارس بهتر، سرمایهٔ اجتماعی بیشتر، و خانواده‌های دووالده بیشتر.', 'Chetty et al. (2014, tax data on 40 million people): mobility in the US varies two- to threefold between cities; five strong correlates: less racial and spatial segregation, less inequality, better schools, more social capital, and more two-parent families.', [chetty]),
              pt('«منحنی گتسبی بزرگ»: کشورهای نابرابرتر تحرک کمتری دارند؛ نابرابری نتیجه، نابرابری فرصت نسل بعد می‌شود.', 'The "Great Gatsby curve": more unequal countries have less mobility; inequality of outcome becomes the next generation\'s inequality of opportunity.', [chetty, piketty])],
      links=[ln('tabar:gwas-polygenic', 'bridges', 'سهم ژن و خانواده در تحصیلات', 'The share of genes and family in education'), ln('soc:gini-inequality', 'prerequisite', 'اندازه‌گیری نابرابری', 'Measuring inequality')])

S.add('inequality-health', 'concept', t('نابرابری و سلامت جامعه', 'Inequality and the health of society', 'Ongelijkheid en de gezondheid van de samenleving'),
      t('ویلکینسون و پیکت ادعا کردند در کشورهای ثروتمند، نه ثروت که نابرابری است که با امید به زندگی، اعتماد، جرم، سلامت روان و چاقی همبسته است. تز پرنفوذی که داده‌هایش را منتقدان جدی به چالش کشیده‌اند؛ همبستگی هست، علیت و اندازه محل بحث است.', 'Wilkinson and Pickett claimed that among rich countries it is inequality, not wealth, that correlates with life expectancy, trust, crime, mental health and obesity. An influential thesis whose data serious critics have challenged; the correlation exists, causation and magnitude are debated.', 'Wilkinson en Pickett stelden dat onder rijke landen niet rijkdom maar ongelijkheid samenhangt met levensverwachting, vertrouwen, criminaliteit, mentale gezondheid en obesitas. Een invloedrijke these waarvan serieuze critici de data hebben aangevochten; de correlatie bestaat, causaliteit en omvang zijn omstreden.'),
      parent='inequality', field='inequality', people=[P['wilkinson']],
      points=[pt('«تراز روح» (۲۰۰۹): در ۲۳ کشور ثروتمند و ۵۰ ایالت آمریکا، شاخص ترکیبی مشکلات اجتماعی با نابرابری همبستگی قوی و با درآمد سرانه همبستگی ناچیز دارد؛ سازوکار پیشنهادی: استرس مقایسه و منزلت.', '"The Spirit Level" (2009): across 23 rich countries and 50 US states, a composite index of social problems correlates strongly with inequality and barely with income per head; the proposed mechanism is status and comparison stress.', [wilkinson]),
              pt('نقد (ساندرز ۲۰۱۰ و دیگران): انتخاب کشورها و شاخص‌ها نتیجه را عوض می‌کند، چند همبستگی با حذف یکی دو کشور پرت از بین می‌رود، و فرهنگ و تاریخ به‌عنوان متغیر سوم کنترل نشده‌اند. فراتحلیل‌های بعدی اثر نابرابری بر سلامت را «کوچک ولی واقعی» برآورد کرده‌اند.', 'Critique (Saunders 2010 and others): the choice of countries and indices changes the result, several correlations vanish when one or two outliers are dropped, and culture and history are uncontrolled third variables. Later meta-analyses estimate the effect of inequality on health as "small but real".', [saunders], ['contested', 'editor-note'])],
      links=[ln('soc:generalized-trust', 'explains', 'نابرابری و اعتماد', 'Inequality and trust'), ln('psy:n-stress', 'bridges', 'استرس منزلت در بدن', 'Status stress in the body'), ln('soc:gini-inequality', 'prerequisite', 'اندازه‌گیری نابرابری', 'Measuring inequality')])

# ---------- institutions
S.add('institutions-inclusive', 'concept', t('نهادهای فراگیر و بهره‌کش', 'Inclusive and extractive institutions', 'Inclusieve en extractieve instituties'),
      t('چرا ملت‌ها شکست می‌خورند؟ عجم‌اوغلو و رابینسون: نه جغرافیا و نه فرهنگ، بلکه نهادهای سیاسی و اقتصادی. نهاد فراگیر به اکثریت اجازهٔ مشارکت و مالکیت امن می‌دهد؛ نهاد بهره‌کش ثروت را از اکثریت به اقلیت حاکم منتقل می‌کند و نوآوری را، چون قدرت را تهدید می‌کند، سرکوب.', 'Why do nations fail? Acemoglu and Robinson: neither geography nor culture, but political and economic institutions. Inclusive institutions let the majority participate and hold property securely; extractive ones move wealth from the majority to a ruling minority and suppress innovation because it threatens power.', 'Waarom falen naties? Acemoglu en Robinson: niet geografie of cultuur, maar politieke en economische instituties. Inclusieve instituties laten de meerderheid deelnemen en veilig bezitten; extractieve verplaatsen rijkdom van de meerderheid naar een heersende minderheid en onderdrukken innovatie omdat ze de macht bedreigt.'),
      parent='institutions', field='institutions', people=[P['acemoglu'], P['north']],
      points=[pt('نورث (۱۹۹۰): نهادها «قواعد بازی»اند، رسمی و غیررسمی، و با کاهش عدم قطعیت هزینهٔ مبادله را پایین می‌آورند؛ وابستگی به مسیر توضیح می‌دهد چرا نهادهای ناکارآمد دوام می‌آورند.', 'North (1990): institutions are the "rules of the game", formal and informal, lowering transaction costs by reducing uncertainty; path dependence explains why inefficient institutions persist.', [north]),
              pt('عجم‌اوغلو، جانسون و رابینسون (۲۰۰۱): با مرگ‌ومیر مهاجران اروپایی به‌عنوان متغیر ابزاری نشان دادند مستعمره‌هایی که اروپاییان در آن ساکن شدند نهادهای فراگیر و امروز درآمد بالاتر دارند. مقاله‌ای بنیادین که داده‌های مرگ‌ومیرش را آلبوی (۲۰۱۲) زیر سؤال برد؛ نوبل اقتصاد ۲۰۲۴ به همین پژوهش داده شد.', 'Acemoglu, Johnson and Robinson (2001): using European settler mortality as an instrument, showed colonies where Europeans settled got inclusive institutions and higher incomes today. A foundational paper whose mortality data Albouy (2012) questioned; the 2024 Nobel in economics went to this research.', [ajr, albouy], ['contested']),
              pt('نفت نمونهٔ کلاسیک «نفرین منابع» است: درآمدی که بی‌نیاز از مالیات شهروندان است، پاسخ‌گویی را کم و نهادهای بهره‌کش را پایدار می‌کند؛ این الگو برای ایران بسیار بحث شده است.', 'Oil is the classic "resource curse": revenue that needs no taxation of citizens lowers accountability and stabilises extractive institutions; this pattern has been much debated for Iran.', [ar2012], ['editor-note'])],
      links=[ln('soc:generalized-trust', 'explains', 'فساد، نهادها و اعتماد', 'Corruption, institutions and trust'), ln('soc:collective-action', 'see-also', 'چگونه نهادها تغییر می‌کنند', 'How institutions change'), ln('psy:human-progress', 'bridges', 'پیشرفت انسانی در ویکی روان', 'Human progress in the psychology wiki')])

S.add('protestant-ethic', 'concept', t('اخلاق پروتستانی و روح سرمایه‌داری', 'The Protestant ethic and the spirit of capitalism', 'De protestantse ethiek en de geest van het kapitalisme'),
      t('وبر پرسید چرا سرمایه‌داری عقلانی اول در اروپای پروتستان شکوفا شد و پاسخ داد: کار سخت و ریاضت‌کشانه به‌عنوان نشانهٔ رستگاری، پس‌انداز به جای مصرف، و حساب‌گری روزمره. تز پرنفوذی که شواهد تجربی‌اش مختلط است.', 'Weber asked why rational capitalism first flourished in Protestant Europe and answered: ascetic hard work as a sign of salvation, saving over consumption, and everyday calculation. An influential thesis with mixed empirical evidence.', 'Weber vroeg waarom het rationele kapitalisme eerst in protestants Europa opbloeide en antwoordde: ascetisch hard werken als teken van verlossing, sparen boven consumeren, en alledaagse berekening. Een invloedrijke these met gemengd empirisch bewijs.'),
      parent='institutions', field='institutions', people=[P['weber'], P['henrich']],
      points=[pt('وبر (۱۹۰۵): هدف نشان دادن «قرابت انتخابی» میان یک اخلاق دینی و یک نظام اقتصادی بود، نه علیت یک‌طرفه؛ خودش هشدار داد که «قفس آهنین» سرمایه‌داری دیگر به روح دینی نیازی ندارد.', 'Weber (1905): the aim was to show an "elective affinity" between a religious ethic and an economic system, not one-way causation; he himself warned that capitalism\'s "iron cage" no longer needs the religious spirit.', [weber]),
              pt('هنریک (۲۰۲۰) روایت جایگزین می‌دهد: ممنوعیت‌های کلیسای غربی بر ازدواج خویشاوندی خانواده‌های گسترده را شکست و روان‌شناسی «فردگرا، غیرشخصی و تحلیلی» ساخت که بعدها بازار و دموکراسی روی آن سوار شد؛ پروتستانتیسم بیشتر سوادآموزی را بالا برد تا اخلاق کار.', 'Henrich (2020) offers an alternative account: the Western Church\'s bans on cousin marriage broke extended kin groups and produced an "individualist, impersonal, analytic" psychology on which markets and democracy later rode; Protestantism raised literacy more than the work ethic.', [henrich2020], ['contested'])],
      links=[ln('tabar:consanguinity', 'bridges', 'ازدواج خویشاوندی و ساختار خانواده', 'Cousin marriage and family structure'), ln('psy:cultural-evolution', 'bridges', 'تکامل فرهنگی', 'Cultural evolution'), ln('soc:secularization', 'see-also', 'دین در جامعهٔ مدرن', 'Religion in modern society')])

# ---------- collective action
S.add('collective-action', 'concept', t('مسئلهٔ کنش جمعی و سواری مجانی', 'The collective action problem and free-riding', 'Het collectieve-actieprobleem en meeliften'),
      t('اگر همه از نتیجه سود می‌برند چه شرکت کنند چه نکنند، عقلانی است که کسی هزینه ندهد؛ پس کالاهای عمومی کمتر از نیاز تولید می‌شوند و گروه‌های بزرگ سخت‌تر از گروه‌های کوچک بسیج می‌شوند. استروم نشان داد اجتماعات محلی این مسئله را قرن‌ها بدون دولت و بدون بازار حل کرده‌اند.', 'If everyone benefits from the outcome whether or not they take part, it is rational for no one to bear the cost; so public goods are under-produced and large groups mobilise with more difficulty than small ones. Ostrom showed local communities have solved this for centuries without state or market.', 'Als iedereen van de uitkomst profiteert, of hij nu meedoet of niet, is het rationeel dat niemand de kosten draagt; dus worden publieke goederen te weinig geproduceerd en mobiliseren grote groepen moeilijker dan kleine. Ostrom toonde dat lokale gemeenschappen dit eeuwenlang hebben opgelost zonder staat of markt.'),
      parent='collective', field='collective', people=[P['olson'], P['ostrom']],
      points=[pt('اولسون (۱۹۶۵): گروه‌های کوچک با منافع متمرکز (یک صنف) بر گروه‌های بزرگ با منافع پراکنده (مصرف‌کنندگان) پیروز می‌شوند؛ از همین رو سیاست‌گذاری به سمت لابی‌های کوچک کج می‌شود.', 'Olson (1965): small groups with concentrated interests (a trade lobby) beat large groups with diffuse interests (consumers); hence policy tilts toward small lobbies.', [olson]),
              pt('استروم (۱۹۹۰): در ده‌ها نمونهٔ مرتع، آبیاری و شیلات، اجتماعات محلی با هشت اصل طراحی (مرز روشن، قواعد متناسب با محل، مشارکت در قاعده‌گذاری، پایش، مجازات پلکانی، حل اختلاف ارزان، به رسمیت شناخته شدن، لایه‌بندی) منابع مشترک را پایدار نگه داشتند. قنات‌های ایران از نمونه‌های کلاسیک این ادبیات‌اند.', 'Ostrom (1990): in dozens of pasture, irrigation and fishery cases, local communities kept commons sustainable with eight design principles (clear boundaries, locally fitted rules, participation in rule-making, monitoring, graduated sanctions, cheap conflict resolution, recognition, nesting). Iran\'s qanats are classic cases in this literature.', [ostrom])],
      links=[ln('psy:cooperation-competition', 'bridges', 'همکاری در ویکی روان', 'Cooperation in the psychology wiki'), ln('psy:fairness', 'bridges', 'انصاف و تنبیه نوع‌دوستانه', 'Fairness and altruistic punishment'), ln('soc:social-movements', 'prerequisite', 'جنبش‌ها به‌عنوان حل مسئلهٔ کنش جمعی', 'Movements as solutions to the collective action problem')])

S.add('social-movements', 'concept', t('جنبش‌های اجتماعی و سیاست اعتراضی', 'Social movements and contentious politics', 'Sociale bewegingen en contentieuze politiek'),
      t('جنبش، کارزاری پایدار با نمایش «ارزشمندی، وحدت، تعداد و تعهد» است. چه چیزی جنبش می‌سازد؟ نارضایتی همیشه هست؛ فرق را منابع، فرصت‌های سیاسی و «قاب‌بندی» می‌گذارند. و شواهد کمّی می‌گویند مقاومت بی‌خشونت تاریخاً بیش از مسلحانه به نتیجه رسیده، هرچند نرخ موفقیتش در دههٔ اخیر افت کرده.', 'A movement is a sustained campaign displaying "worthiness, unity, numbers and commitment". What makes one? Grievance is always there; resources, political opportunities and "framing" make the difference. And the quantitative evidence says nonviolent resistance has historically succeeded more often than armed struggle, though its success rate has fallen in the last decade.', 'Een beweging is een volgehouden campagne die "waardigheid, eenheid, aantallen en toewijding" toont. Wat maakt haar? Grieven zijn er altijd; middelen, politieke kansen en "framing" maken het verschil. En het kwantitatieve bewijs zegt dat geweldloos verzet historisch vaker slaagde dan gewapende strijd, al is het slagingspercentage het laatste decennium gedaald.'),
      parent='collective', field='collective', people=[P['tilly'], P['chenoweth'], P['bayat']],
      points=[pt('تیلی (۲۰۰۴) و تارو (۲۰۱۱): «رپرتوار اعتراض» (تظاهرات، اعتصاب، طومار) اختراع مدرن است و با دولت ملی و رسانه رشد کرد؛ چرخه‌های اعتراض با باز شدن فرصت سیاسی اوج می‌گیرند و با سرکوب یا نهادینه شدن فرو می‌نشینند.', 'Tilly (2004) and Tarrow (2011): the "repertoire of contention" (demonstration, strike, petition) is a modern invention that grew with the nation-state and media; cycles of protest peak as political opportunity opens and subside with repression or institutionalisation.', [tilly, tarrow]),
              pt('چنووت و استفان (۲۰۱۱، ۳۲۳ کارزار ۱۹۰۰–۲۰۰۶): کارزارهای بی‌خشونت ۵۳ درصد و مسلحانه ۲۶ درصد موفق بودند؛ هیچ کارزاری با مشارکت فعال ۳٫۵ درصد جمعیت شکست نخورد. چنووت (۲۰۲۱): از ۲۰۱۰ نرخ موفقیت بی‌خشونت به زیر ۳۵ درصد افتاده؛ «قاعدهٔ ۳٫۵ درصد» توصیفی است نه تضمین.', 'Chenoweth and Stephan (2011, 323 campaigns 1900–2006): nonviolent campaigns succeeded 53 percent of the time, armed ones 26 percent; no campaign with active participation of 3.5 percent of the population failed. Chenoweth (2021): since 2010 nonviolent success has fallen below 35 percent; the "3.5 percent rule" is descriptive, not a guarantee.', [chenoweth, chenoweth2021], ['contested']),
              pt('بیات (۲۰۱۰) برای خاورمیانه مفهوم «ناجنبش» را ساخت: تغییر آرام و پراکندهٔ زندگی روزمره توسط میلیون‌ها نفر معمولی (پوشش، کار غیررسمی، حضور زنان در فضای عمومی) که رهبر و سازمان ندارد ولی مرزها را جابه‌جا می‌کند؛ «پیشروی آرام مردم عادی».', 'Bayat (2010) coined "nonmovements" for the Middle East: the quiet, dispersed change of everyday life by millions of ordinary people (dress, informal work, women\'s presence in public space) with no leader or organisation, yet shifting boundaries; "the quiet encroachment of the ordinary".', [bayat])],
      links=[ln('soc:preference-falsification', 'explains', 'چرا بسیج ناگهانی است', 'Why mobilisation is sudden'), ln('soc:collective-action', 'prerequisite', 'مسئلهٔ کنش جمعی', 'The collective action problem'), ln('psy:polarization', 'bridges', 'قطبی شدن در ویکی روان', 'Polarization in the psychology wiki')])

S.add('preference-falsification', 'concept', t('تحریف ترجیحات و غافلگیری انقلاب‌ها', 'Preference falsification and the surprise of revolutions', 'Voorkeursvervalsing en de verrassing van revoluties'),
      t('وقتی ابراز مخالفت هزینه دارد، مردم در جمع چیزی می‌گویند که باور ندارند؛ پس هیچ‌کس نمی‌داند چند نفر مثل او فکر می‌کنند، حتی حکومت. یک جرقهٔ کوچک می‌تواند آستانه‌های پنهان را پشت سر هم بیندازد و رژیمی که دیروز پایدار می‌نمود امروز فرو بریزد. برای همین انقلاب‌ها، از جمله ۱۳۵۷، همیشه «تصورناپذیر» بوده‌اند.', 'When expressing dissent is costly, people say in public what they do not believe; so no one knows how many think like them, not even the regime. A small spark can trip hidden thresholds in a cascade, and a regime that looked stable yesterday collapses today. That is why revolutions, including 1979, were always "unthinkable".', 'Wanneer afwijkende meningen uiten kostbaar is, zeggen mensen in het openbaar wat ze niet geloven; dus weet niemand hoeveel anderen zo denken, zelfs het regime niet. Een kleine vonk kan verborgen drempels in een cascade doen omslaan, en een regime dat gisteren stabiel leek, stort vandaag in. Daarom waren revoluties, ook die van 1979, altijd "ondenkbaar".'),
      parent='collective', field='collective', people=[P['kuran'], P['kurzman']],
      points=[pt('کوران (۱۹۹۱): هر فرد آستانه‌ای دارد («وقتی این‌قدر نفر بیرون باشند، من هم می‌آیم»)؛ توزیع این آستانه‌ها پنهان است، پس هم ثبات ظاهری و هم فروپاشی ناگهانی هر دو قابل توضیح‌اند و پیش‌بینی ساختاری ناممکن است.', 'Kuran (1991): each person has a threshold ("when this many are out, I join"); the distribution of thresholds is hidden, so both apparent stability and sudden collapse are explicable and structural prediction is impossible.', [kuran]),
              pt('کرزمن (۲۰۰۴): انقلاب ایران را نه ساختارها (اقتصاد، دولت، دین) که «تجربهٔ زیستهٔ» مردم توضیح می‌دهد: تا پاییز ۱۳۵۷ اکثریت انقلاب را ممکن نمی‌دانستند و درست وقتی ممکن شد که مردم دیدند دیگران هم به خیابان آمده‌اند. ناجنبش‌های بیات و آبشار کوران در همین‌جا به هم می‌رسند.', 'Kurzman (2004): the Iranian revolution is explained less by structures (economy, state, religion) than by people\'s "lived experience": until autumn 1978 most thought revolution impossible, and it became possible exactly when people saw others in the street. Bayat\'s nonmovements and Kuran\'s cascade meet here.', [kurzman])],
      links=[ln('soc:social-movements', 'explains', 'پویایی بسیج', 'The dynamics of mobilisation'), ln('psy:norm-psychology', 'bridges', 'روان‌شناسی هنجار و ناآگاهی جمعی', 'Norm psychology and pluralistic ignorance'), ln('psy:conspiracy', 'see-also', 'باور و اطلاعات در جامعهٔ بسته', 'Belief and information in a closed society')])

# ---------- values
S.add('value-change', 'concept', t('تغییر ارزش‌ها: از بقا به ابراز خود', 'Value change: from survival to self-expression', 'Waardeverandering: van overleving naar zelfexpressie'),
      t('اینگلهارت با پنجاه سال پیمایش در صد کشور نشان داد با امنیت اقتصادی و وجودی، ارزش‌ها از «بقا» (نظم، سنت، دین) به «ابراز خود» (آزادی، برابری جنسیتی، تحمل تفاوت) می‌چرخند؛ تغییر بیشتر از راه جایگزینی نسل‌هاست تا تغییر عقیدهٔ افراد. ایران روی این نقشه حرکت کرده است.', 'Inglehart, with fifty years of surveys in a hundred countries, showed that with economic and existential security values turn from "survival" (order, tradition, religion) to "self-expression" (freedom, gender equality, tolerance of difference); change comes more through generational replacement than individuals changing their minds. Iran has moved on this map.', 'Inglehart toonde met vijftig jaar surveys in honderd landen dat waarden met economische en existentiële zekerheid verschuiven van "overleving" (orde, traditie, religie) naar "zelfexpressie" (vrijheid, gendergelijkheid, tolerantie); verandering komt meer door generatiewisseling dan doordat individuen van mening veranderen. Iran heeft zich op deze kaart bewogen.'),
      parent='values', field='values', iran='iran:values-shift', people=[P['inglehart']],
      points=[pt('اینگلهارت و ولزل (۲۰۰۵): دو محور «سنتی–سکولارعقلانی» و «بقا–ابراز خود» بیشتر واریانس ارزش‌های جهان را می‌گیرند؛ توسعه کشورها را روی هر دو به جلو می‌راند، ولی میراث فرهنگی (مسیحی، اسلامی، کنفوسیوسی…) جای شروع را تعیین می‌کند.', 'Inglehart and Welzel (2005): two axes, "traditional–secular-rational" and "survival–self-expression", capture most of the world\'s variance in values; development pushes countries forward on both, but cultural heritage (Christian, Islamic, Confucian…) sets the starting point.', [inglehart2005]),
              pt('اینگلهارت (۲۰۱۸): تغییر ارزش‌ها نسلی است و زمانی خودش را در سیاست نشان می‌دهد که نسل جدید اکثریت شود؛ ناامنی تازه (بحران اقتصادی، مهاجرت) می‌تواند واکنش «اقتدارگرایانه» بسازد، اما روند بلندمدت را برنگردانده است.', 'Inglehart (2018): value change is generational and shows up in politics when the new cohort becomes the majority; new insecurity (economic crisis, migration) can produce an "authoritarian reflex", but has not reversed the long-run trend.', [inglehart2018], ['contested']),
              pt('در سه موج پیمایش ملی ارزش‌ها و نگرش‌های ایرانیان (۱۳۷۹، ۱۳۸۲، ۱۳۹۴) و موج‌های پیمایش جهانی ارزش‌ها، ایران روی محور بقا–ابراز خود جابه‌جا شده: افزایش اهمیت آزادی فردی و برابری جنسیتی، به‌ویژه در نسل‌های جوان‌تر و شهرها.', 'Across the three waves of the national Iranian Values and Attitudes survey (2000, 2003, 2015) and the World Values Survey waves, Iran has moved on the survival–self-expression axis: rising weight of individual freedom and gender equality, especially among younger cohorts and in cities.', [ivas, wvs7])],
      links=[ln('soc:generations', 'explains', 'سازوکار نسلی تغییر', 'The generational mechanism of change'), ln('soc:secularization', 'see-also', 'دین', 'Religion'), ln('psy:p-personality', 'bridges', 'ارزش‌ها در روان‌شناسی', 'Values in psychology')])

S.add('secularization', 'concept', t('سکولار شدن: امنیت وجودی و دین', 'Secularization: existential security and religion', 'Secularisering: existentiële zekerheid en religie'),
      t('نظریهٔ کلاسیک می‌گفت مدرنیته دین را کم‌رنگ می‌کند؛ آمریکا و جهان اسلام استثنا به نظر می‌رسیدند. نوریس و اینگلهارت پاسخ دادند: متغیر اصلی «امنیت وجودی» است؛ هرجا زندگی امن و پیش‌بینی‌پذیر شود، دین‌داری افت می‌کند، و چون جمعیت کشورهای دین‌دار سریع‌تر رشد می‌کند، جهان در کل سکولار نمی‌شود.', 'The classic theory said modernity fades religion; America and the Muslim world looked like exceptions. Norris and Inglehart replied: the key variable is "existential security"; wherever life becomes safe and predictable religiosity falls, and because religious countries\' populations grow faster, the world as a whole does not secularise.', 'De klassieke theorie zei dat moderniteit religie doet verbleken; Amerika en de islamitische wereld leken uitzonderingen. Norris en Inglehart antwoordden: de sleutelvariabele is "existentiële zekerheid"; waar het leven veilig en voorspelbaar wordt, daalt religiositeit, en omdat de bevolking van religieuze landen sneller groeit, seculariseert de wereld als geheel niet.'),
      parent='values', field='values', iran='iran:religiosity', people=[P['inglehart'], P['durkheim']],
      points=[pt('نوریس و اینگلهارت (۲۰۱۱): دین‌داری با آسیب‌پذیری (فقر، بیماری، ناامنی) همبستگی قوی دارد؛ در کشورهای ثروتمندِ با دولت رفاه قوی، حضور در عبادتگاه و اهمیت خدا در زندگی پایین‌ترین است. آمریکا با نابرابری و ناامنی بالاترش تا حدی توضیح داده می‌شود.', 'Norris and Inglehart (2011): religiosity correlates strongly with vulnerability (poverty, illness, insecurity); in rich countries with strong welfare states, attendance and the importance of God in life are lowest. America is partly explained by its higher inequality and insecurity.', [norris]),
              pt('دادهٔ ایران: پیمایش ملی ارزش‌ها و نگرش‌ها افت نسلی در مناسک جمعی (نماز جماعت، مسجد) همراه با پایداری باورهای شخصی را نشان می‌دهد؛ پیمایش آنلاین گمان (۲۰۲۰، حدود ۵۰ هزار پاسخ‌گو) سهم بالایی از «بی‌دین» یا «معنوی بدون دین» گزارش کرد، اما نمونه‌اش غیراحتمالی و اینترنتی است و نباید با پیمایش ملی یکی گرفته شود.', 'Iranian data: the national Values and Attitudes survey shows a generational fall in collective ritual (congregational prayer, mosque) alongside stable personal belief; the online GAMAAN survey (2020, about 50,000 respondents) reported a high share of "non-religious" or "spiritual but not religious", but its sample is non-probability and internet-based and must not be equated with a national survey.', [ivas, gamaan], ['contested', 'editor-note']),
              pt('دورکیم: کارکرد دین پیش از هر چیز انسجام جمعی است («جامعه خودش را می‌پرستد»)؛ از این رو با افول مناسک، نهادهای جایگزینِ هم‌بستگی (ورزش، ملی‌گرایی، جنبش‌ها) پر می‌شوند.', 'Durkheim: religion\'s function is first of all collective cohesion ("society worships itself"); hence as ritual declines, substitute institutions of solidarity (sport, nationalism, movements) fill the space.', [durk_division])],
      links=[ln('soc:value-change', 'part-of', 'بخشی از تغییر ارزش‌ها', 'Part of value change'), ln('psy:meaning-making', 'bridges', 'معناسازی در ویکی روان', 'Meaning-making in the psychology wiki'), ln('soc:protestant-ethic', 'see-also', 'دین و اقتصاد', 'Religion and economy')])

S.add('generations', 'concept', t('نسل‌ها: مسئلهٔ مانهایم', 'Generations: Mannheim\'s problem', 'Generaties: het probleem van Mannheim'),
      t('هم‌سن بودن نسل نمی‌سازد؛ تجربهٔ مشترک رویدادهای بزرگ در سال‌های شکل‌گیری (۱۷ تا ۲۵ سالگی) نسل می‌سازد. برچسب‌های «دههٔ شصتی، هشتادی» تا جایی معنا دارند که به چنین تجربهٔ مشترکی اشاره کنند؛ وگرنه سن، دوره و نسل را قاطی می‌کنند.', 'Being the same age does not make a generation; the shared experience of great events in the formative years (17 to 25) does. Labels like "the sixties-born, the eighties-born" are meaningful insofar as they point to such shared experience; otherwise they confuse age, period and cohort.', 'Even oud zijn maakt geen generatie; de gedeelde ervaring van grote gebeurtenissen in de vormende jaren (17 tot 25) wel. Labels als "de jaren-zestig-geborenen" zijn betekenisvol voor zover ze naar zo\'n gedeelde ervaring verwijzen; anders verwarren ze leeftijd, periode en cohort.'),
      parent='values', field='values', people=[P['mannheim']],
      points=[pt('مانهایم (۱۹۲۸): «موقعیت نسلی» (هم‌زمانی تولد) تنها امکان است؛ «نسل بالفعل» وقتی پدید می‌آید که هم‌سالان در جریان تاریخی مشترکی درگیر شوند، و درون آن «واحدهای نسلی» متفاوت و حتی متخاصم شکل می‌گیرند.', 'Mannheim (1928): "generational location" (being born together) is only a possibility; an "actual generation" arises when age-peers are caught up in a shared historical current, and within it different, even hostile, "generation units" form.', [mannheim]),
              pt('مسئلهٔ روش‌شناختی: هر تفاوت مشاهده‌شده میان جوانان و پیران می‌تواند اثر سن (همه با پیری محافظه‌کارتر می‌شوند)، اثر دوره (همه در یک بحران تغییر می‌کنند) یا اثر نسل باشد؛ جدا کردن این سه با داده‌های مقطعی ناممکن است و نیاز به پیمایش‌های تکرارشونده دارد.', 'The methodological problem: any observed difference between young and old may be an age effect (everyone grows more conservative), a period effect (everyone changes in a crisis) or a cohort effect; separating the three is impossible with cross-sectional data and needs repeated surveys.', [inglehart2018], ['editor-note'])],
      links=[ln('soc:value-change', 'explains', 'تغییر ارزش‌ها از راه جایگزینی نسل‌ها', 'Value change through generational replacement'), ln('psy:adolescence', 'bridges', 'نوجوانی و سال‌های شکل‌گیری', 'Adolescence and the formative years')])

# ---------- space
S.add('urbanism', 'concept', t('شهرنشینی به‌مثابه شیوهٔ زندگی', 'Urbanism as a way of life', 'Urbanisme als levenswijze'),
      t('ورث گفت اندازه، تراکم و ناهمگونی شهر روابط را سطحی، نقش‌ها را تکه‌تکه و کنترل اجتماعی غیررسمی را ضعیف می‌کند. سه‌چهارم ایرانیان اکنون شهرنشین‌اند؛ جابه‌جایی‌ای که در یک نسل رخ داد و بسیاری از تنش‌های ارزشی امروز را توضیح می‌دهد.', 'Wirth argued that a city\'s size, density and heterogeneity make relations superficial, roles fragmented and informal social control weak. Three-quarters of Iranians now live in cities; a shift that happened within one generation and explains many of today\'s value tensions.', 'Wirth stelde dat omvang, dichtheid en heterogeniteit van de stad relaties oppervlakkig, rollen gefragmenteerd en informele sociale controle zwak maken. Driekwart van de Iraniërs woont nu in steden; een verschuiving binnen één generatie die veel van de huidige waardespanningen verklaart.'),
      parent='space', field='space', iran='iran:urbanization',
      points=[pt('ورث (۱۹۳۸): تعریف جامعه‌شناختی شهر: سکونت‌گاه بزرگ، متراکم و دائمیِ افراد ناهمگون؛ پیامدها: روابط ثانویه و ابزاری، تخصصی شدن، تحمل تفاوت، و در عین حال بی‌نامی و آنومی.', 'Wirth (1938): the sociological definition of a city: a large, dense, permanent settlement of heterogeneous individuals; consequences: secondary and instrumental relations, specialisation, tolerance of difference, and also anonymity and anomie.', [wirth]),
              pt('سرشماری ۱۳۹۵: ۷۴ درصد جمعیت ایران شهرنشین است، در برابر حدود ۳۱ درصد در ۱۳۳۵؛ تهران و حاشیه‌اش بیش از ۱۵ میلیون نفر. نقدِ ورث: روستاییان مهاجر در شهر اغلب «روستای درون شهر» می‌سازند و پیوندهای قوی را حفظ می‌کنند.', 'The 2016 census: 74 percent of Iran\'s population is urban, against about 31 percent in 1956; Tehran and its periphery exceed 15 million. The critique of Wirth: rural migrants in the city often build a "village in the city" and keep strong ties.', [sci2016])],
      links=[ln('soc:migration-theories', 'see-also', 'مهاجرت', 'Migration'), ln('soc:anomie', 'explains', 'آنومی شهری', 'Urban anomie'), ln('psy:belonging', 'bridges', 'تعلق در ویکی روان', 'Belonging in the psychology wiki')])

S.add('migration-theories', 'concept', t('نظریه‌های مهاجرت', 'Theories of migration', 'Migratietheorieën'),
      t('چرا مردم مهاجرت می‌کنند و چرا ادامه می‌دهند؟ اقتصاد نئوکلاسیک می‌گوید اختلاف دستمزد؛ «اقتصاد نوین مهاجرت» می‌گوید خانواده برای پراکندن ریسک یک نفر را می‌فرستد؛ نظریهٔ شبکه می‌گوید هر مهاجر هزینهٔ مهاجرت بعدی را کم می‌کند، برای همین مهاجرت خودتداوم‌بخش است.', 'Why do people migrate and why does it continue? Neoclassical economics says wage gaps; the "new economics of migration" says the household sends one member to spread risk; network theory says each migrant lowers the cost of the next, which is why migration sustains itself.', 'Waarom migreren mensen en waarom gaat het door? De neoklassieke economie zegt loonverschillen; de "nieuwe migratie-economie" zegt dat het huishouden één lid stuurt om risico te spreiden; de netwerktheorie zegt dat elke migrant de kosten voor de volgende verlaagt, waardoor migratie zichzelf in stand houdt.'),
      parent='space', field='space',
      points=[pt('مسی و همکاران (۱۹۹۳): نظریه‌ها رقیب نیستند، لایه‌های مختلف یک پدیده‌اند: آغاز مهاجرت را عوامل ساختاری و اقتصادی توضیح می‌دهند، تداومش را شبکه‌ها و نهادها («علیت انباشتی»).', 'Massey et al. (1993): the theories are not rivals but layers of one phenomenon: structural and economic factors explain the start of migration, networks and institutions its continuation ("cumulative causation").', [massey]),
              pt('برای ایران، مهاجرت تحصیل‌کردگان («فرار مغزها») و مهاجرت از افغانستان به ایران دو جریان بزرگ‌اند که هر دو با نظریهٔ شبکه بهتر از اختلاف دستمزد توضیح داده می‌شوند؛ آمار دقیق مهاجرت خروجی ایران رسماً منتشر نمی‌شود و برآوردها پراکنده‌اند.', 'For Iran, the emigration of the educated ("brain drain") and migration from Afghanistan into Iran are the two large flows, both better explained by network theory than by wage gaps; precise statistics on emigration from Iran are not officially published and estimates vary widely.', [massey], ['editor-note'])],
      links=[ln('soc:weak-ties', 'explains', 'شبکه‌ها در مهاجرت', 'Networks in migration'), ln('tabar:ancient-dna', 'bridges', 'مهاجرت در مقیاس هزاره‌ها', 'Migration on the scale of millennia'), ln('soc:urbanism', 'see-also', 'شهر مقصد', 'The destination city')])

S.add('network-society', 'concept', t('جامعهٔ شبکه‌ای', 'The network society', 'De netwerkmaatschappij'),
      t('کاستلز: در عصر اطلاعات، قدرت و ثروت در «فضای جریان‌ها» (شبکه‌های مالی، رسانه‌ای، فنی) جابه‌جا می‌شود و از «فضای مکان‌ها» (شهر، کشور) جدا می‌افتد؛ هویت‌های مقاومت (ملی، دینی، محلی) پاسخِ آدم‌های جامانده‌اند.', 'Castells: in the information age, power and wealth move in the "space of flows" (financial, media, technical networks) and come loose from the "space of places" (city, country); resistance identities (national, religious, local) are the response of those left behind.', 'Castells: in het informatietijdperk bewegen macht en rijkdom in de "ruimte van stromen" (financiële, media-, technische netwerken) en raken los van de "ruimte van plaatsen" (stad, land); verzetsidentiteiten (nationaal, religieus, lokaal) zijn het antwoord van wie achterblijft.'),
      parent='space', field='space', people=[P['castells']],
      points=[pt('کاستلز (۱۹۹۶): شبکه شکل سازمانی غالب می‌شود چون انعطاف‌پذیر، مقیاس‌پذیر و بقاپذیر است؛ اما منطقش «دوگانه» است: یا درون شبکه‌ای یا بی‌ارزش. این تز پیش از شبکه‌های اجتماعی نوشته شد و بسیاری از پیش‌بینی‌هایش را آن‌ها تأیید کردند.', 'Castells (1996): the network becomes the dominant organisational form because it is flexible, scalable and survivable; but its logic is "binary": either you are in the network or you are worthless. The thesis was written before social media and many of its predictions were borne out by them.', [castells])],
      links=[ln('soc:weak-ties', 'prerequisite', 'ساختار شبکه', 'Network structure'), ln('psy:polarization', 'bridges', 'قطبی شدن در شبکه‌ها', 'Polarization in networks'), ln('soc:social-movements', 'see-also', 'جنبش‌های شبکه‌ای', 'Networked movements')])

# ---------- Iran notes
S.iran('social-trust', {'fa': 'اعتماد تعمیم‌یافتهٔ ایرانیان چقدر است؟', 'en': 'How high is Iranians\' generalised trust?'},
       {'fa': 'در پیمایش جهانی ارزش‌ها حدود ۱۰ تا ۱۵ درصد می‌گویند «به بیشتر مردم می‌شود اعتماد کرد» (ردهٔ کشورهای کم‌اعتماد)؛ پیمایش ملی ارزش‌ها و نگرش‌ها نیز کاهش اعتماد به مردم را از موج اول (۱۳۷۹) تا سوم (۱۳۹۴) نشان می‌دهد. رقم دقیق به موج و شیوهٔ نمونه‌گیری وابسته است.', 'en': 'In the World Values Survey about 10 to 15 percent say "most people can be trusted" (a low-trust country); the national Values and Attitudes survey also shows trust in people falling from wave 1 (2000) to wave 3 (2015). Exact figures depend on wave and sampling.'},
       2020, 'national probability surveys (WVS; IVAS)', 'B', [wvs7, ivas], ['soc:generalized-trust'], [7], critique='سؤال واحد و ترجمه‌اش در ایران بحث‌برانگیز است؛ اعتماد «خاص» (به خانواده و آشنایان) بالا و «عام» پایین است و باید جدا گزارش شود.')
S.iran('gini', {'fa': 'نابرابری درآمد در ایران چقدر است؟', 'en': 'How unequal is income in Iran?'},
       {'fa': 'ضریب جینی در دههٔ اخیر حدود ۳۸ تا ۴۲ (بانک جهانی و مرکز آمار)؛ پس از ۱۳۹۰ کمی کاهش و در سال‌های تورم بالا دوباره افزایش. نابرابری ثروت اندازه‌گیری رسمی ندارد.', 'en': 'The Gini has been about 38 to 42 in the last decade (World Bank and Statistical Centre); a slight fall after 2011 and renewed rise in high-inflation years. Wealth inequality has no official measurement.'},
       2022, 'household budget surveys', 'B', [wb_gini], ['soc:gini-inequality'], [10])
S.iran('values-shift', {'fa': 'ارزش‌های ایرانیان در دو دههٔ اخیر چگونه تغییر کرده؟', 'en': 'How have Iranians\' values changed over two decades?'},
       {'fa': 'سه موج پیمایش ملی (۱۳۷۹، ۱۳۸۲، ۱۳۹۴) و موج‌های WVS: افزایش اهمیت آزادی فردی، برابری جنسیتی و تحمل تفاوت، به‌ویژه در جوانان و شهرها؛ کاهش اعتماد اجتماعی و اعتماد نهادی؛ پایداری اهمیت خانواده.', 'en': 'Three national waves (2000, 2003, 2015) and WVS waves: rising weight of individual freedom, gender equality and tolerance, especially among the young and in cities; falling social and institutional trust; stable importance of family.'},
       2015, 'repeated national surveys', 'B', [ivas, wvs7], ['soc:value-change'], [4, 7], critique='فاصلهٔ موج‌ها نامنظم و پرسش‌ها کاملاً یکسان نیست؛ مقایسهٔ دقیق نیاز به هماهنگ‌سازی دارد.')
S.iran('religiosity', {'fa': 'دین‌داری در ایران چقدر تغییر کرده است؟', 'en': 'How much has religiosity in Iran changed?'},
       {'fa': 'پیمایش ملی: افت نسلی مناسک جمعی همراه با پایداری باور شخصی. پیمایش آنلاین گمان (۲۰۲۰): سهم بالای بی‌دینی/معنویت بدون دین، اما نمونهٔ غیراحتمالی اینترنتی. نتیجهٔ محتاطانه: کاهش دین‌داری نهادی قطعی، اندازهٔ دقیقش نامعلوم.', 'en': 'National survey: generational fall in collective ritual with stable personal belief. Online GAMAAN survey (2020): high share of non-religion/spirituality without religion, but a non-probability internet sample. Cautious conclusion: a fall in institutional religiosity is certain, its exact size unknown.'},
       2020, 'national survey + online non-probability survey', 'C', [ivas, gamaan], ['soc:secularization'], [4, 7], contested=True, critique='پیمایش آنلاین با نمونهٔ خودگزین را نمی‌توان به کل جمعیت تعمیم داد؛ پیمایش ملی نیز در موضوع دین با سوگیری «پاسخ مطلوب اجتماعی» روبه‌روست.')
S.iran('urbanization', {'fa': 'شهرنشینی در ایران چقدر و چقدر سریع بوده است؟', 'en': 'How urban is Iran, and how fast did it get there?'},
       {'fa': 'سرشماری ۱۳۹۵: ۷۴ درصد شهرنشین (از حدود ۳۱ درصد در ۱۳۳۵)؛ تهران و حومه بیش از ۱۵ میلیون نفر.', 'en': '2016 census: 74 percent urban (from about 31 percent in 1956); Tehran and periphery over 15 million.'},
       2016, 'national census', 'A', [sci2016], ['soc:urbanism'], [10])

# ---------- demography (added)
abbasi = S.src('Abbasi-Shavazi, M. J., McDonald, P., & Hosseini-Chavoshi, M. (2009). The Fertility Transition in Iran: Revolution and Reproduction. Springer.', 2, 'https://doi.org/10.1007/978-90-481-3198-3')
unpop = S.src('United Nations, Department of Economic and Social Affairs, Population Division (2024). World Population Prospects 2024.', 3, 'https://population.un.org/wpp/')
lee = S.src('Lee, R. (2003). The demographic transition: Three centuries of fundamental change. Journal of Economic Perspectives, 17(4), 167–190.', 1, 'https://doi.org/10.1257/089533003772034943')
lutz = S.src('Lutz, W., & KC, S. (2011). Global human capital: Integrating education and population. Science, 333(6042), 587–592.', 1, 'https://doi.org/10.1126/science.1206964')
P['abbasi'] = S.person('Mohammad Jalal Abbasi-Shavazi', 'محمدجلال عباسی‌شوازی', '', 'جمعیت‌شناسی؛ گذار باروری ایران')
S.add('demography', 'field', t('جمعیت', 'Population', 'Bevolking'), t('گذار جمعیتی، افت باروری و سالمندی: آرام‌ترین و بزرگ‌ترین تغییر اجتماعی قرن.', 'Demographic transition, fertility decline and ageing: the quietest and largest social change of the century.', 'Demografische transitie, dalende vruchtbaarheid en vergrijzing: de stilste en grootste sociale verandering van de eeuw.'), parent='soc')
S.add('demographic-transition', 'concept', t('گذار جمعیتی', 'The demographic transition', 'De demografische transitie'),
      t('همهٔ جوامع از «مرگ‌ومیر بالا، زادوولد بالا» به «هر دو پایین» می‌روند؛ در فاصلهٔ این دو، جمعیت چند برابر می‌شود. اروپا این راه را در دو قرن رفت؛ ایران در دو دهه.', 'Every society moves from "high mortality, high fertility" to "both low"; in between, population multiplies. Europe took two centuries; Iran took two decades.', 'Elke samenleving gaat van "hoge sterfte, hoge vruchtbaarheid" naar "beide laag"; daartussen vermenigvuldigt de bevolking zich. Europa deed er twee eeuwen over; Iran twee decennia.'),
      parent='demography', field='demography',
      points=[pt('لی (۲۰۰۳): از ۱۸۰۰ تا ۲۱۰۰ جمعیت جهان از یک به حدود ده میلیارد می‌رسد و امید به زندگی از حدود ۳۰ به بالای ۸۰ سال؛ گذار با افت مرگ‌ومیر کودکان آغاز می‌شود و افت باروری یک تا دو نسل بعد می‌آید.', 'Lee (2003): from 1800 to 2100 world population rises from one to about ten billion and life expectancy from about 30 to over 80; the transition starts with falling child mortality, and fertility falls one or two generations later.', [lee]),
              pt('«پنجرهٔ جمعیتی»: وقتی باروری افتاده ولی سالمندی هنوز نرسیده، سهم جمعیت در سن کار بیشینه است؛ اگر اشتغال و آموزش فراهم باشد سود جمعیتی می‌دهد، وگرنه بیکاری جوانان. ایران از دههٔ ۱۳۸۰ در این پنجره است.', 'The "demographic window": when fertility has fallen but ageing has not yet arrived, the working-age share peaks; with jobs and schooling it yields a demographic dividend, otherwise youth unemployment. Iran has been in this window since the 2000s.', [lutz])],
      links=[ln('soc:iran-fertility', 'applies-to', 'نمونهٔ ایران', 'The Iranian case'), ln('tabar:common-ancestors', 'bridges', 'ریاضی نسل‌ها', 'The mathematics of generations')])
S.add('iran-fertility', 'concept', t('گذار باروری ایران: از ۶٫۵ به زیر ۲', 'Iran\'s fertility transition: from 6.5 to below 2', 'De Iraanse vruchtbaarheidstransitie: van 6,5 naar onder de 2'),
      t('یکی از سریع‌ترین افت‌های باروری ثبت‌شده در جهان: میانگین فرزند هر زن از حدود ۶٫۵ در اوایل دههٔ ۱۳۶۰ به حدود ۲ در ۱۳۷۹ و زیر ۲ پس از آن رسید؛ با سواد زنان، شهرنشینی، شبکهٔ بهداشت روستایی و برنامهٔ تنظیم خانواده. سیاست‌های تشویقی دههٔ ۱۳۹۰ روند را برنگرداندند.', 'One of the fastest fertility declines ever recorded: children per woman fell from about 6.5 in the early 1980s to about 2 in 2000 and below 2 after; driven by women\'s literacy, urbanisation, the rural health network and the family planning programme. Pronatalist policies of the 2010s did not reverse the trend.', 'Een van de snelste vruchtbaarheidsdalingen ooit geregistreerd: kinderen per vrouw daalde van zo\'n 6,5 begin jaren tachtig naar ongeveer 2 in 2000 en daaronder nadien; gedreven door alfabetisering van vrouwen, verstedelijking, het rurale gezondheidsnetwerk en het gezinsplanningsprogramma. Pronatalistisch beleid in de jaren 2010 keerde de trend niet.'),
      parent='demography', field='demography', iran='iran:fertility', people=[P['abbasi']],
      points=[pt('عباسی‌شوازی، مک‌دونالد و حسینی‌چاووشی (۲۰۰۹): افت باروری در همهٔ استان‌ها، شهر و روستا و همهٔ سطوح سواد رخ داد؛ عامل کلیدی، تغییر «ایده‌آل خانواده» و دسترسی به وسایل پیشگیری از راه خانه‌های بهداشت بود، نه فقط توسعهٔ اقتصادی.', 'Abbasi-Shavazi, McDonald and Hosseini-Chavoshi (2009): fertility fell in every province, in cities and villages and at all literacy levels; the key factors were a changed "family ideal" and access to contraception through rural health houses, not economic development alone.', [abbasi]),
              pt('سازمان ملل (۲۰۲۴): نرخ باروری کل ایران حدود ۱٫۷؛ جمعیت در میانهٔ قرن به اوج می‌رسد و سپس سالمند می‌شود. همین الگو در ترکیه، تونس و بسیاری از کشورهای اسلامی دیده می‌شود و «استثنای فرهنگی» را رد می‌کند.', 'United Nations (2024): Iran\'s total fertility rate about 1.7; population peaks mid-century and then ages. The same pattern appears in Turkey, Tunisia and many other Muslim countries, refuting a "cultural exception".', [unpop])],
      links=[ln('soc:demographic-transition', 'part-of', 'نمونه‌ای از گذار جمعیتی', 'A case of demographic transition'), ln('soc:value-change', 'explains', 'تغییر ایده‌آل خانواده', 'The changed family ideal'), ln('soc:urbanism', 'see-also', 'شهرنشینی', 'Urbanisation')])
S.iran('fertility', {'fa': 'باروری در ایران چقدر و چگونه افت کرد؟', 'en': 'How far and how did fertility fall in Iran?'},
       {'fa': 'از حدود ۶٫۵ فرزند به ازای هر زن در اوایل دههٔ ۱۳۶۰ به حدود ۲ در ۱۳۷۹ و حدود ۱٫۷ در دههٔ ۱۴۰۰؛ افت در همهٔ استان‌ها و سطوح سواد. سیاست‌های تشویقی اخیر روند را برنگردانده‌اند.', 'en': 'From about 6.5 children per woman in the early 1980s to about 2 in 2000 and about 1.7 in the 2020s; the decline occurred in all provinces and literacy levels. Recent pronatalist policies have not reversed it.'},
       2024, 'census and DHS-type surveys; UN estimates', 'A', [abbasi, unpop], ['soc:iran-fertility'], [2, 10])

S.write()
